using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Windows.Forms;
using CreatorSettlement;
public static class TestsHistory {
 static int passed;static string dir;static readonly BindingFlags FI=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
 static object Field(object x,string name){return x.GetType().GetField(name,FI).GetValue(x);}
 static object Call(object x,string name,params object[] args){return x.GetType().GetMethod(name,FI).Invoke(x,args);}
 static DataRow Row(DataTable t,string col,string id){return t.AsEnumerable().First(r=>Model.Val(r,col)==id);}
 static Sheet Read(string file){var s=Xlsx.Read(file)[0];s.SetHeader(1);return s;}
 static void Edit(MainWindow f,DataGridView grid,string key,string id,string column,string value){var row=grid.Rows.Cast<DataGridViewRow>().First(r=>Convert.ToString(r.Cells[key].Value)==id);grid.CurrentCell=row.Cells[column];Assert(grid.BeginEdit(true),"editable cell begins edit "+column);((TextBox)grid.EditingControl).Text=value;Assert(grid.EndEdit(),"editable cell commits "+column);Call(f,"Commit");Application.DoEvents();}
 static void Change(MainWindow f,string name,Action action){Call(f,"RunChange",name,action);}
 static Receipt Info(string suffix="0001"){return new Receipt{Channel="银行卡",Account="622200000000"+suffix,Name="演示用户",Phone="13800008000",Identity="110101199001010010"};}
 [STAThread] public static int Main(string[] args){try{dir=args[0];Directory.CreateDirectory(dir);CultureInfo.CurrentCulture=CultureInfo.InvariantCulture;Application.EnableVisualStyles();using(var f=new MainWindow()){f.Opacity=0;f.ShowInTaskbar=false;f.Show();var sheets=new List<Sheet>{(Sheet)typeof(TestsV13).GetMethod("Input",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null)};typeof(MainWindow).GetField("sheets",FI).SetValue(f,sheets);var choice=(ComboBox)Field(f,"sheetChoice");typeof(MainWindow).GetField("busy",FI).SetValue(f,true);choice.Items.Add("演示明细");choice.SelectedIndex=0;typeof(MainWindow).GetField("busy",FI).SetValue(f,false);Call(f,"LoadSelected");var m=(Model)Field(f,"model");var check=(DataGridView)Field(f,"checkGrid");var adjust=(DataGridView)Field(f,"adjustGrid");var undo=(Button)Field(f,"undoButton");var redo=(Button)Field(f,"redoButton");Assert(!undo.Enabled&&!redo.Enabled,"history initially empty");Assert(!adjust.ReadOnly&&!adjust.Columns["线上成本"].ReadOnly,"adjustment manual columns unlocked");
  Edit(f,check,"任务/方案ID","T1","一口价（无手续费）","999");Assert((decimal)m.Check.Rows[0][8]==-759m&&undo.Enabled,"negative fixed price edit recorded");undo.PerformClick();Assert(m.Check.Rows[0].IsNull(7)&&(decimal)m.Check.Rows[0][8]==240m&&redo.Enabled,"button undo restores blank and calculated payment");redo.PerformClick();Assert((decimal)m.Check.Rows[0][7]==999m&&(decimal)m.Check.Rows[0][8]==-759m,"button redo restores negative settlement");
  Call(f,"Navigate",3);Edit(f,adjust,"任务ID","T1","线上成本","123.45");Assert((decimal)Row(m.Adjust,"任务ID","T1")[4]==123.45m,"manual online cost saved");Call(f,"Navigate",0);Call(f,"Navigate",3);Assert((decimal)Row(m.Adjust,"任务ID","T1")[4]==123.45m,"navigation preserves manual cost");m.ExportAdjust(Path.Combine(dir,"manual-cost.xlsx"));Assert(Read(Path.Combine(dir,"manual-cost.xlsx")).Get(2,"线上成本")=="123.45","actual adjustment export uses manual cost");Call(f,"Undo");Assert((decimal)Row(m.Adjust,"任务ID","T1")[4]==1m,"manual cost undo restores previous cost");Call(f,"Redo");Assert((decimal)Row(m.Adjust,"任务ID","T1")[4]==123.45m,"manual cost redo restores decimal");
  Call(f,"Navigate",0);Call(f,"SyncAdjustment");Assert((decimal)Row(m.Adjust,"任务ID","T1")[4]==999m,"sync replaces manual cost explicitly");Call(f,"Undo");Assert((decimal)Row(m.Adjust,"任务ID","T1")[4]==123.45m&&(decimal)m.Check.Rows[0][7]==999m,"undo sync restores manual cost without losing fixed price");Call(f,"Redo");Assert((decimal)Row(m.Adjust,"任务ID","T1")[4]==999m,"redo sync restores matched cost");
  Call(f,"Navigate",3);var filter=(GridFilter)Field(f,"adjustFilter");filter.SelectValues("任务ID",new[]{"T2"});m.Adjust.DefaultView.Sort="[任务ID] DESC";Edit(f,adjust,"任务ID","T2","线上成本","-12.34");Assert((decimal)Row(m.Adjust,"任务ID","T2")[4]==-12.34m,"filtered sorted edit matches task with negative cost");Call(f,"Undo");Assert((decimal)Row(m.Adjust,"任务ID","T2")[4]==1m&&m.Adjust.DefaultView.Count==1,"undo retains view filter and restores correct task");Call(f,"Redo");Assert((decimal)Row(m.Adjust,"任务ID","T2")[4]==-12.34m,"redo filtered cost");Edit(f,adjust,"任务ID","T2","线上成本","");Assert(Row(m.Adjust,"任务ID","T2").IsNull(4),"blank cost allowed");Call(f,"Undo");Assert((decimal)Row(m.Adjust,"任务ID","T2")[4]==-12.34m,"undo blank restores numeric value");Edit(f,adjust,"任务ID","T2","线上成本","7.89");Assert(!redo.Enabled,"new edit clears redo branch");int count=((System.Collections.ICollection)Field(f,"undoSteps")).Count;Edit(f,adjust,"任务ID","T2","线上成本","7.89");Assert(((System.Collections.ICollection)Field(f,"undoSteps")).Count==count,"unchanged edit creates no history");
  var store=(ReceiptStore)Field(f,"receiptStore");string initial=store.Snapshot();string id=null;Change(f,"新增收款记录",()=>{id=store.Save(Info());Call(f,"RefreshReceipts",id);});Call(f,"Undo");Assert(store.Snapshot()==initial&&new ReceiptStore(store.Path).Snapshot()==initial,"undo receipt creation persists to disk");Call(f,"Redo");Assert(store.Records.Any(r=>r.Id==id)&&new ReceiptStore(store.Path).Records.Any(r=>r.Id==id),"redo receipt preserves ID and disk");Change(f,"编辑收款记录",()=>store.Save(Info("0002"),id));Call(f,"Undo");Assert(store.Records.Single(r=>r.Id==id).Info.Account.EndsWith("0001"),"undo receipt edit");Call(f,"Redo");Assert(store.Records.Single(r=>r.Id==id).Info.Account.EndsWith("0002"),"redo receipt edit");Change(f,"删除收款记录",()=>store.Delete(id));Call(f,"Undo");Assert(store.Records.Any(r=>r.Id==id),"undo receipt deletion restores stable ID");Call(f,"Redo");Assert(!store.Records.Any(r=>r.Id==id),"redo receipt deletion");Call(f,"Undo");Call(f,"RefreshReceipts",id);Call(f,"Navigate",1);var before=m.Payment.Copy();Call(f,"UseSelectedReceipt");Assert(m.Payment.AsEnumerable().All(r=>Model.Val(r,"姓名(必填)")=="演示用户"),"actual receipt apply operation");Call(f,"Undo");Assert(m.Payment.Rows.Count==before.Rows.Count&&m.Payment.Rows[0]["姓名(必填)"].Equals(before.Rows[0]["姓名(必填)"]),"undo receipt application restores full payment");Call(f,"Redo");Assert(m.Payment.AsEnumerable().All(r=>Model.Val(r,"收款账号").EndsWith("0002")),"redo payment restores expression account");
  int beforeRows=m.Payment.Rows.Count;Change(f,"录入团长打款金额",()=>m.UseLeaderAmount(Info(),Info("0003"),50m,new[]{"T1"}));Assert(m.Payment.Rows.Count==beforeRows+1,"leader pair creates two records");Call(f,"Undo");Assert(m.Payment.Rows.Count==beforeRows&&Model.Val(Row(m.Payment,"任务ID","T1"),"团长比例")=="1","undo leader pair restores single record and ratio");Call(f,"Redo");Assert(m.Payment.Rows.Count==beforeRows+1&&m.Payment.AsEnumerable().Where(r=>Model.Val(r,"任务ID")=="T1").All(r=>r.IsNull("团长比例")&&Model.Val(r,"团长打款金额")=="50"),"redo restores paired amount and blank ratio");
  var message=new Message();var keyArgs=new object[]{message,Keys.Control|Keys.Z};Assert((bool)Call(f,"ProcessCmdKey",keyArgs)&&m.Payment.Rows.Count==beforeRows,"Ctrl Z executes undo");keyArgs=new object[]{message,Keys.Control|Keys.Y};Assert((bool)Call(f,"ProcessCmdKey",keyArgs)&&m.Payment.Rows.Count==beforeRows+1,"Ctrl Y executes redo");
  int oldHistory=((System.Collections.ICollection)Field(f,"undoSteps")).Count;try{Change(f,"失败操作",()=>{m.Adjust.Rows[0][4]=42m;throw new Exception("test");});throw new Exception("Expected failure");}catch(TargetInvocationException){}Assert(((System.Collections.ICollection)Field(f,"undoSteps")).Count==oldHistory&&(decimal)m.Adjust.Rows[0][4]!=42m,"failed action rolls back without history");
  Call(f,"Navigate",3);filter.Clear();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(0,0,f.Width,f.Height));b.Save(Path.Combine(dir,"ui-history-adjust.png"));}Assert(undo.Parent.ClientRectangle.Contains(undo.Bounds)&&redo.Parent.ClientRectangle.Contains(redo.Bounds),"history buttons fit toolbar");
  Call(f,"Navigate",0);check.CurrentCell=check.Rows[0].Cells[7];Assert(check.BeginEdit(true),"active edit begins before shortcut");((TextBox)check.EditingControl).Text="1001";keyArgs=new object[]{message,Keys.Control|Keys.Z};Call(f,"ProcessCmdKey",keyArgs);Assert((decimal)m.Check.Rows[0][7]==999m&&(decimal)m.Check.Rows[0][8]==-759m,"undo commits then reverses active cell edit");keyArgs=new object[]{message,Keys.Control|Keys.Shift|Keys.Z};Call(f,"ProcessCmdKey",keyArgs);Assert((decimal)m.Check.Rows[0][7]==1001m&&(decimal)m.Check.Rows[0][8]==-761m,"Ctrl Shift Z redo recalculates active edit payment");
  Edit(f,check,"任务/方案ID","T1","备注","手动备注");Call(f,"Undo");Assert(Model.Val(m.Check.Rows[0],"备注")!="手动备注","undo check note edit");Call(f,"Redo");Assert(Model.Val(m.Check.Rows[0],"备注")=="手动备注","redo check note edit");
  for(int i=0;i<60;i++){int value=i;Change(f,"金额修改",()=>m.Adjust.Rows[0][4]=(decimal)value);}Assert(((System.Collections.ICollection)Field(f,"undoSteps")).Count==50,"history bounded to 50 steps");Call(f,"LoadSelected");Assert(!undo.Enabled&&!redo.Enabled,"new source clears history");f.Hide();}
  Console.WriteLine("TOTAL "+passed+" history and manual cost assertions passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
}
